'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import * as fabric from 'fabric';
import { enterCropMode } from 'fabric/extensions';
import { AlignCenter, AlignHorizontalJustifyCenter, AlignHorizontalJustifyEnd, AlignHorizontalJustifyStart, AlignVerticalJustifyCenter, AlignVerticalJustifyEnd, AlignVerticalJustifyStart, BringToFront, Circle, Copy, Crop, Download, Eye, EyeOff, FilePlus2, FolderOpen, Group, ImagePlus, Layers3, Lock, Magnet, Plus, Redo2, Save, SendToBack, Square, Trash2, Type, Ungroup, Unlock, Undo2, X } from 'lucide-react';

type ProjectListItem = { id: string; name: string; updatedAt: string };
type StockImage = { id: number; alt: string; photographer: string; thumb: string; full: string };
type PageData = { id: string; name: string; w: number; h: number; bg: string; json: object; thumb?: string };
type LibraryItem = { id: string; name: string; updatedAt: string };
type BrandKit = LibraryItem & { colors: string[]; fontFamily: string; logos: string[]; images: string[] };
type Inspector = { fill: string; opacity: number; angle: number; fontSize: number; isText: boolean; isImage: boolean; canRound: boolean; radius: number; shadowOn: boolean; shadowIntensity: number; fontFamily: string; fontWeight: string; fontStyle: string; underline: boolean; charSpacing: number; lineHeight: number; textAlign: string };
const SIZES = [{ name: 'Cuadrado', w: 1080, h: 1080 }, { name: 'Historia', w: 1080, h: 1920 }, { name: 'Horizontal', w: 1200, h: 630 }, { name: 'A4', w: 1240, h: 1754 }];
const COLORS = ['#18181b', '#f8fafc', '#ff4d6d', '#ffb703', '#3a86ff', '#8338ec', '#06d6a0'];
const BRAND_PALETTES = [
  { name: 'Vibrante', colors: ['#18181b', '#ff4d6d', '#ffb703', '#3a86ff', '#f8fafc'] },
  { name: 'Editorial', colors: ['#151515', '#f4efe6', '#b23a2f', '#d1a85b', '#ffffff'] },
  { name: 'Natural', colors: ['#233d2c', '#6f8f72', '#d8c9a7', '#f4f1e8', '#b8663b'] },
  { name: 'Nocturna', colors: ['#0b1020', '#202a44', '#7357ff', '#21d4a4', '#f5f7ff'] },
];
const TEXT_STYLE_KEYS = new Set(['fill', 'fontFamily', 'fontSize', 'fontWeight', 'fontStyle', 'underline', 'stroke', 'strokeWidth']);
(fabric.FabricObject as typeof fabric.FabricObject & { customProperties: string[] }).customProperties = ['name'];

export default function Editor() {
  const canvasNode = useRef<HTMLCanvasElement>(null);
  const canvas = useRef<fabric.Canvas | null>(null);
  const history = useRef<string[]>([]);
  const historyIndex = useRef(-1);
  const restoring = useRef(false);
  const snapGuides = useRef<{ x?: number; y?: number }>({});
  const snappingRef = useRef(true);
  const pagesRef = useRef<PageData[]>([]);
  const savedNameRef = useRef('');
  const [name, setName] = useState('Mi diseño');
  const [projectId, setProjectId] = useState('');
  const [size, setSize] = useState({ w: 1080, h: 1080 });
  const [customWidth, setCustomWidth] = useState('1080');
  const [customHeight, setCustomHeight] = useState('1080');
  const [zoom, setZoom] = useState(56);
  const [projects, setProjects] = useState<ProjectListItem[]>([]);
  const [layers, setLayers] = useState<fabric.FabricObject[]>([]);
  const [selected, setSelected] = useState(false);
  const [selectionType, setSelectionType] = useState<'none' | 'single' | 'multiple' | 'group'>('none');
  const [snapping, setSnapping] = useState(true);
  const [inspector, setInspector] = useState<Inspector>({ fill: '#18181b', opacity: 100, angle: 0, fontSize: 72, isText: false, isImage: false, canRound: false, radius: 0, shadowOn: false, shadowIntensity: 45, fontFamily: 'Arial', fontWeight: '400', fontStyle: 'normal', underline: false, charSpacing: 0, lineHeight: 1.16, textAlign: 'left' });
  const [status, setStatus] = useState('Listo');
  const [canUndo, setCanUndo] = useState(false);
  const [canRedo, setCanRedo] = useState(false);
  const [mediaQuery, setMediaQuery] = useState('texturas abstractas');
  const [media, setMedia] = useState<StockImage[]>([]);
  const [mediaLoading, setMediaLoading] = useState(false);
  const [mediaMode, setMediaMode] = useState<'photos' | 'icons'>('photos');
  const [icons, setIcons] = useState<string[]>([]);
  const [pages, setPages] = useState<PageData[]>([]);
  const [activePageId, setActivePageId] = useState('');
  const [templates, setTemplates] = useState<LibraryItem[]>([]);
  const [brands, setBrands] = useState<BrandKit[]>([]);
  const [palette, setPalette] = useState(COLORS);
  const [lastSaved, setLastSaved] = useState('Sin guardar');
  const [brandModalOpen, setBrandModalOpen] = useState(false);
  const [editingBrandId, setEditingBrandId] = useState('');
  const [activeBrandId, setActiveBrandId] = useState('');
  const [brandSaving, setBrandSaving] = useState(false);
  const [brandDraft, setBrandDraft] = useState({ name: '', fontFamily: 'Arial', colors: BRAND_PALETTES[0].colors, logos: [] as string[], images: [] as string[] });

  const syncUi = useCallback(() => {
    const c = canvas.current; if (!c) return;
    setLayers([...c.getObjects()].reverse());
    const o = c.getActiveObject(); setSelected(Boolean(o));
    setSelectionType(!o ? 'none' : o.type === 'activeselection' ? 'multiple' : o.type === 'group' ? 'group' : 'single');
    if (o) {
      const imageClip = o.type === 'image' && o.clipPath?.type === 'rect' ? o.clipPath as fabric.Rect : null;
      const radiusPx = o.type === 'rect' ? Number((o as fabric.Rect).rx || 0) : Number(imageClip?.rx || 0);
      const radiusBase = Math.max(1, Math.min(Number(o.width || 1), Number(o.height || 1)) / 2);
      const shadow = o.shadow instanceof fabric.Shadow ? o.shadow : null;
      setInspector({ fill: typeof o.fill === 'string' ? o.fill : '#18181b', opacity: Math.round((o.opacity ?? 1) * 100), angle: Math.round(o.angle ?? 0), fontSize: 'fontSize' in o ? Number(o.fontSize) : 72, isText: o.type === 'textbox' || o.type === 'i-text', isImage: o.type === 'image', canRound: o.type === 'rect' || o.type === 'image', radius: Math.round(Math.min(100, radiusPx / radiusBase * 100)), shadowOn: Boolean(shadow), shadowIntensity: shadow ? Math.round(Math.max(0, Math.min(100, (shadow.blur - 4) / .3))) : 45, fontFamily: 'fontFamily' in o ? String(o.fontFamily) : 'Arial', fontWeight: 'fontWeight' in o ? String(o.fontWeight) : '400', fontStyle: 'fontStyle' in o ? String(o.fontStyle) : 'normal', underline: 'underline' in o ? Boolean(o.underline) : false, charSpacing: 'charSpacing' in o ? Number(o.charSpacing) : 0, lineHeight: 'lineHeight' in o ? Number(o.lineHeight) : 1.16, textAlign: 'textAlign' in o ? String(o.textAlign) : 'left' });
    }
  }, []);

  const snapshot = useCallback(() => {
    if (restoring.current || !canvas.current) return;
    const next = JSON.stringify(canvas.current.toJSON());
    if (history.current[historyIndex.current] === next) return;
    history.current = history.current.slice(0, historyIndex.current + 1);
    history.current.push(next); if (history.current.length > 40) history.current.shift();
    historyIndex.current = history.current.length - 1;
    setCanUndo(historyIndex.current > 0); setCanRedo(false); syncUi();
  }, [syncUi]);

  const attachCrop = useCallback((c: fabric.Canvas) => {
    c.getObjects('image').forEach((object) => {
      object.off('mousedblclick', enterCropMode);
      object.once('mousedblclick', enterCropMode);
    });
  }, []);

  const refreshCroppedImage = useCallback((object?: fabric.FabricObject) => {
    if (!object || object.type !== 'image') return;
    object.dirty = true;
    object.setCoords();
    object.canvas?.requestRenderAll();
  }, []);

  useEffect(() => {
    if (!canvasNode.current) return;
    const c = new fabric.Canvas(canvasNode.current, { width: size.w, height: size.h, backgroundColor: '#ffffff', preserveObjectStacking: true, selectionColor: 'rgba(255,77,109,.12)', selectionBorderColor: '#ff4d6d' });
    canvas.current = c;
    c.on('object:added', snapshot); c.on('object:modified', snapshot); c.on('object:removed', snapshot);
    c.on('selection:created', syncUi); c.on('selection:updated', syncUi); c.on('selection:cleared', syncUi);
    c.on('object:added', () => attachCrop(c));
    c.on('object:moving', (event) => {
      if (!snappingRef.current || !event.target) return;
      const object = event.target;
      const center = object.getCenterPoint();
      const threshold = 12;
      let snapX: number | undefined;
      let snapY: number | undefined;
      const xTargets = [c.width / 2];
      const yTargets = [c.height / 2];
      c.getObjects().filter((candidate) => candidate !== object).forEach((candidate) => {
        const point = candidate.getCenterPoint(); xTargets.push(point.x); yTargets.push(point.y);
      });
      const nearX = xTargets.find((value) => Math.abs(center.x - value) <= threshold);
      const nearY = yTargets.find((value) => Math.abs(center.y - value) <= threshold);
      if (nearX !== undefined) { snapX = nearX; object.setPositionByOrigin(new fabric.Point(nearX, object.getCenterPoint().y), 'center', 'center'); }
      if (nearY !== undefined) { snapY = nearY; object.setPositionByOrigin(new fabric.Point(object.getCenterPoint().x, nearY), 'center', 'center'); }
      snapGuides.current = { x: snapX, y: snapY }; c.requestRenderAll();
    });
    c.on('mouse:up', (event) => { snapGuides.current = {}; refreshCroppedImage(event.target); c.requestRenderAll(); });
    c.on('mouse:dblclick', (event) => {
      const target = event.target;
      requestAnimationFrame(() => refreshCroppedImage(target));
    });
    c.on('after:render', () => {
      const context = c.getTopContext(); const { x, y } = snapGuides.current;
      context.save(); context.strokeStyle = '#ff4d6d'; context.lineWidth = 2; context.setLineDash([10, 8]);
      if (x !== undefined) { context.beginPath(); context.moveTo(x, 0); context.lineTo(x, c.height); context.stroke(); }
      if (y !== undefined) { context.beginPath(); context.moveTo(0, y); context.lineTo(c.width, y); context.stroke(); }
      context.restore();
    });
    snapshot();
    const firstPage: PageData = { id: `page-${Date.now()}`, name: 'Página 1', w: size.w, h: size.h, bg: '#ffffff', json: c.toJSON() };
    pagesRef.current = [firstPage]; setPages([firstPage]); setActivePageId(firstPage.id);
    void refreshProjects(); void refreshLibraries();
    return () => { c.dispose(); canvas.current = null; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function refreshProjects() { try { setProjects(await (await fetch('/api/projects')).json()); } catch { setStatus('No pude leer los proyectos'); } }
  async function refreshLibraries() { try { const [templateList, brandList] = await Promise.all([fetch('/api/library/templates').then((r) => r.json()), fetch('/api/library/brands').then((r) => r.json())]); setTemplates(templateList); setBrands(brandList); } catch { setStatus('No pude leer plantillas o marcas'); } }
  function setPagesSynced(next: PageData[]) { pagesRef.current = next; setPages(next); }
  function capturePage(page?: PageData): PageData | null { const c = canvas.current; if (!c) return null; const base = page || pagesRef.current.find((item) => item.id === activePageId) || pagesRef.current[0] || { id: activePageId || `page-${Date.now()}`, name: 'Página 1', w: c.width, h: c.height, bg: '#ffffff', json: { objects: [] } }; return { ...base, w: c.width, h: c.height, bg: String(c.backgroundColor || '#ffffff'), json: c.toJSON() }; }
  function commitCurrentPage() { const current = capturePage(); if (!current) return pagesRef.current; const exists = pagesRef.current.some((item) => item.id === current.id); const next = exists ? pagesRef.current.map((item) => item.id === current.id ? current : item) : [...pagesRef.current, current]; setPagesSynced(next); if (!activePageId) setActivePageId(current.id); return next; }
  async function openPage(id: string) { const c = canvas.current; const target = pagesRef.current.find((item) => item.id === id); if (!c || !target || id === activePageId) return; commitCurrentPage(); restoring.current = true; c.setDimensions({ width: target.w, height: target.h }); setSize({ w: target.w, h: target.h }); setCustomWidth(String(target.w)); setCustomHeight(String(target.h)); await c.loadFromJSON(target.json); c.backgroundColor = target.bg; attachCrop(c); c.requestRenderAll(); restoring.current = false; setActivePageId(id); history.current = []; historyIndex.current = -1; snapshot(); syncUi(); }
  function addPage(duplicatePage = false) { const c = canvas.current; if (!c) return; const list = commitCurrentPage(); const page: PageData = { id: `page-${Date.now()}`, name: `Página ${list.length + 1}`, w: c.width, h: c.height, bg: String(c.backgroundColor || '#ffffff'), json: duplicatePage ? c.toJSON() : { version: fabric.version, objects: [], background: String(c.backgroundColor || '#ffffff') } }; setPagesSynced([...list, page]); setActivePageId(page.id); restoring.current = true; c.clear(); c.setDimensions({ width: page.w, height: page.h }); c.backgroundColor = page.bg; if (duplicatePage) void c.loadFromJSON(page.json).then(() => { attachCrop(c); c.requestRenderAll(); restoring.current = false; snapshot(); syncUi(); }); else { c.requestRenderAll(); restoring.current = false; snapshot(); syncUi(); } setStatus(duplicatePage ? 'Página duplicada' : 'Página nueva'); }
  async function deletePage(id: string) { if (pagesRef.current.length === 1) { setStatus('El documento necesita al menos una página'); return; } const index = pagesRef.current.findIndex((item) => item.id === id); const next = pagesRef.current.filter((item) => item.id !== id); setPagesSynced(next); if (id === activePageId) { setActivePageId(''); await openPage(next[Math.max(0, index - 1)].id); } }
  function movePage(id: string, direction: -1 | 1) { const list = [...pagesRef.current]; const from = list.findIndex((item) => item.id === id); const to = from + direction; if (from < 0 || to < 0 || to >= list.length) return; [list[from], list[to]] = [list[to], list[from]]; setPagesSynced(list); }
  function renamePage(id: string) { const page = pagesRef.current.find((item) => item.id === id); if (!page) return; const nextName = window.prompt('Nombre de la página', page.name); if (!nextName?.trim()) return; setPagesSynced(pagesRef.current.map((item) => item.id === id ? { ...item, name: nextName.trim() } : item)); }
  function add(object: fabric.FabricObject) { const c = canvas.current; if (!c) return; c.add(object); c.centerObject(object); c.setActiveObject(object); c.requestRenderAll(); syncUi(); }
  function addText() { add(new fabric.Textbox('Escribe aquí', { width: 620, fontSize: 92, fontWeight: 700, fontFamily: 'Arial', fill: '#18181b', textAlign: 'center', originX: 'center', originY: 'center' })); }
  function addRect() { add(new fabric.Rect({ width: 420, height: 280, rx: 24, ry: 24, fill: '#ff4d6d', originX: 'center', originY: 'center' })); }
  function addCircle() { add(new fabric.Circle({ radius: 180, fill: '#3a86ff', originX: 'center', originY: 'center' })); }
  async function uploadImage(file?: File) {
    if (!file) return; setStatus('Importando imagen…');
    const form = new FormData(); form.append('file', file);
    try { const response = await fetch('/api/assets', { method: 'POST', body: form }); const result = await response.json(); if (!response.ok || !result.src) throw new Error(result.error || 'Respuesta inválida'); const image = await fabric.FabricImage.fromURL(result.src); const max = Math.min(700 / (image.width || 1), 700 / (image.height || 1), 1); image.scale(max); add(image); if (canvas.current) attachCrop(canvas.current); setStatus(`Guardada en data/assets/${result.filename} · doble clic para recortar`); } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude importar esa imagen'); }
  }
  async function replaceImage(file?: File) { const c = canvas.current; const old = c?.getActiveObject(); if (!file || !c || !old || old.type !== 'image') return; const form = new FormData(); form.append('file', file); setStatus('Reemplazando imagen…'); try { const response = await fetch('/api/assets', { method: 'POST', body: form }); const result = await response.json(); if (!response.ok || !result.src) throw new Error(result.error || 'Respuesta inválida'); const image = await fabric.FabricImage.fromURL(result.src); image.set({ left: old.left, top: old.top, originX: old.originX, originY: old.originY, angle: old.angle, opacity: old.opacity, shadow: old.shadow, clipPath: old.clipPath, scaleX: (old.getScaledWidth() / (image.width || 1)), scaleY: (old.getScaledHeight() / (image.height || 1)) }); c.remove(old); c.add(image); c.setActiveObject(image); attachCrop(c); c.requestRenderAll(); snapshot(); syncUi(); setStatus(`Imagen reemplazada · ${result.filename}`); } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude reemplazar la imagen'); } }
  async function searchMedia(e?: React.FormEvent) { e?.preventDefault(); if (!mediaQuery.trim()) return; setMediaLoading(true); setStatus(mediaMode === 'photos' ? 'Buscando en Pexels…' : 'Buscando en Iconify…'); try { const endpoint = mediaMode === 'photos' ? `/api/media/pexels?q=${encodeURIComponent(mediaQuery)}` : `/api/media/icons?q=${encodeURIComponent(mediaQuery)}`; const response = await fetch(endpoint); const result = await response.json(); if (!response.ok || result.error) throw new Error(result.error || 'Búsqueda fallida'); if (mediaMode === 'photos') { setMedia(result.photos); setStatus(`${result.photos.length} imágenes encontradas`); } else { setIcons(result.icons); setStatus(`${result.icons.length} iconos encontrados`); } } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude buscar recursos'); } finally { setMediaLoading(false); } }
  async function addStockImage(item: StockImage) { setStatus('Guardando imagen en assets…'); try { const response = await fetch('/api/media/image', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ url: item.full, name: item.alt || `pexels-${item.id}` }) }); const result = await response.json(); if (!response.ok || !result.src) throw new Error(result.error || 'Respuesta inválida'); const image = await fabric.FabricImage.fromURL(result.src); const max = Math.min(800 / (image.width || 1), 800 / (image.height || 1), 1); image.scale(max); add(image); if (canvas.current) attachCrop(canvas.current); setStatus(`Crédito: ${item.photographer} · guardada como ${result.filename}`); } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude agregar esa imagen'); } }
  async function addIcon(iconId: string) { const [prefix, iconName] = iconId.split(':'); if (!prefix || !iconName) return; try { const response = await fetch(`/api/media/icons/${prefix}/${iconName}?color=${encodeURIComponent(inspector.fill || '#18181b')}`); if (!response.ok) throw new Error('No pude descargar el ícono'); const { objects, options } = await fabric.loadSVGFromString(await response.text()); const valid = objects.filter((object): object is fabric.FabricObject => Boolean(object)); if (!valid.length) throw new Error('SVG vacío'); const icon = fabric.util.groupSVGElements(valid, options); const scale = 220 / Math.max(icon.width || 220, icon.height || 220); icon.set({ scaleX: scale, scaleY: scale, originX: 'center', originY: 'center' }); add(icon); setStatus(`Ícono ${iconId} insertado como vector editable`); } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude insertar el ícono'); } }
  function remove() { const c = canvas.current; if (!c) return; c.getActiveObjects().forEach((o) => c.remove(o)); c.discardActiveObject(); c.requestRenderAll(); syncUi(); }
  async function duplicate() { const c = canvas.current; const active = c?.getActiveObject(); if (!c || !active) return; const clone = await active.clone(); clone.set({ left: (active.left ?? 0) + 28, top: (active.top ?? 0) + 28 }); c.add(clone); c.setActiveObject(clone); c.requestRenderAll(); }
  async function travel(delta: number) { const c = canvas.current; const next = historyIndex.current + delta; if (!c || next < 0 || next >= history.current.length) return; restoring.current = true; historyIndex.current = next; await c.loadFromJSON(history.current[next]); attachCrop(c); c.requestRenderAll(); restoring.current = false; setCanUndo(next > 0); setCanRedo(next < history.current.length - 1); syncUi(); }
  function patchObject(values: Record<string, unknown>) { const c = canvas.current; const o = c?.getActiveObject(); if (!c || !o) return; const text = o instanceof fabric.Textbox ? o : null; const isRange = text?.isEditing && text.selectionStart !== text.selectionEnd; const isTextStyle = Object.keys(values).every((key) => TEXT_STYLE_KEYS.has(key)); if (text && isRange && isTextStyle) text.setSelectionStyles(values as fabric.TextStyleDeclaration); else o.set(values); o.setCoords(); o.dirty = true; c.requestRenderAll(); snapshot(); syncUi(); }
  function applyRadius(value: number) { const c = canvas.current; const o = c?.getActiveObject(); if (!c || !o) return; const radius = Math.min(Number(o.width || 1), Number(o.height || 1)) / 2 * value / 100; if (o.type === 'rect') (o as fabric.Rect).set({ rx: radius, ry: radius }); else if (o.type === 'image') o.set({ clipPath: value === 0 ? undefined : new fabric.Rect({ width: o.width, height: o.height, rx: radius, ry: radius, originX: 'center', originY: 'center' }) }); o.setCoords(); c.requestRenderAll(); snapshot(); syncUi(); }
  function applyShadow(enabled: boolean, intensity = inspector.shadowIntensity) { const blur = 4 + intensity * .3; const offset = 2 + intensity * .08; const alpha = .15 + intensity * .003; patchObject({ shadow: enabled ? new fabric.Shadow({ color: `rgba(0,0,0,${alpha.toFixed(2)})`, blur, offsetX: offset, offsetY: offset }) : null }); }
  function resize(w: number, h: number) { const c = canvas.current; if (!c) return; c.setDimensions({ width: w, height: h }); setSize({ w, h }); setCustomWidth(String(w)); setCustomHeight(String(h)); c.requestRenderAll(); snapshot(); }
  function applyCustomSize() {
    const w = Math.round(Number(customWidth));
    const h = Math.round(Number(customHeight));
    if (!Number.isFinite(w) || !Number.isFinite(h) || w < 64 || h < 64 || w > 10000 || h > 10000) {
      setStatus('Usa medidas entre 64 y 10,000 px');
      return;
    }
    resize(w, h);
    setStatus(`Lienzo personalizado: ${w} × ${h}px`);
  }
  function layer(action: 'front' | 'back') { const c = canvas.current; const o = c?.getActiveObject(); if (!c || !o) return; action === 'front' ? c.bringObjectToFront(o) : c.sendObjectToBack(o); c.requestRenderAll(); snapshot(); }
  function toggleLayerVisible(object: fabric.FabricObject) { object.set({ visible: !object.visible }); object.dirty = true; canvas.current?.requestRenderAll(); snapshot(); syncUi(); }
  function toggleLayerLock(object: fabric.FabricObject) { const locked = object.selectable === false; object.set({ selectable: locked, evented: locked, lockMovementX: !locked, lockMovementY: !locked, lockScalingX: !locked, lockScalingY: !locked, lockRotation: !locked }); if (!locked) canvas.current?.discardActiveObject(); canvas.current?.requestRenderAll(); snapshot(); syncUi(); }
  function reorderLayer(draggedIndex: number, targetIndex: number) { const c = canvas.current; if (!c || draggedIndex === targetIndex) return; const visual = [...c.getObjects()].reverse(); const object = visual[draggedIndex]; const target = visual[targetIndex]; c.moveObjectTo(object, c.getObjects().indexOf(target)); c.requestRenderAll(); snapshot(); syncUi(); }
  function selectLayer(event: React.MouseEvent, object: fabric.FabricObject) { const c = canvas.current; if (!c || object.selectable === false) return; if (event.ctrlKey || event.metaKey || event.shiftKey) { const selected = c.getActiveObjects(); const objects = selected.includes(object) ? selected.filter((item) => item !== object) : [...selected, object]; c.discardActiveObject(); if (objects.length === 1) c.setActiveObject(objects[0]); else if (objects.length > 1) c.setActiveObject(new fabric.ActiveSelection(objects, { canvas: c })); } else c.setActiveObject(object); c.requestRenderAll(); syncUi(); }
  function renameLayer(object: fabric.FabricObject) { const current = String((object as fabric.FabricObject & { name?: string }).name || object.type); const nextName = window.prompt('Nombre de la capa', current); if (!nextName?.trim()) return; (object as fabric.FabricObject & { name?: string }).name = nextName.trim(); snapshot(); syncUi(); }
  function center() { const c = canvas.current; const o = c?.getActiveObject(); if (!c || !o) return; c.centerObject(o); o.setCoords(); c.requestRenderAll(); snapshot(); }
  function alignToCanvas(mode: 'left' | 'centerH' | 'right' | 'top' | 'centerV' | 'bottom') { const c = canvas.current; const o = c?.getActiveObject(); if (!c || !o) return; const bounds = o.getBoundingRect(); if (mode === 'centerH') c.centerObjectH(o); else if (mode === 'centerV') c.centerObjectV(o); else if (mode === 'left') o.set({ left: (o.left ?? 0) - bounds.left + 24 }); else if (mode === 'right') o.set({ left: (o.left ?? 0) + c.width - bounds.left - bounds.width - 24 }); else if (mode === 'top') o.set({ top: (o.top ?? 0) - bounds.top + 24 }); else o.set({ top: (o.top ?? 0) + c.height - bounds.top - bounds.height - 24 }); o.setCoords(); c.requestRenderAll(); snapshot(); }
  function alignSelection(mode: 'left' | 'centerH' | 'right' | 'top' | 'centerV' | 'bottom') { const c = canvas.current; const active = c?.getActiveObject(); if (!c || !active || active.type !== 'activeselection') return; const objects = (active as fabric.ActiveSelection).getObjects(); const rects = objects.map((object) => ({ object, rect: object.getBoundingRect() })); const left = Math.min(...rects.map(({ rect }) => rect.left)); const right = Math.max(...rects.map(({ rect }) => rect.left + rect.width)); const top = Math.min(...rects.map(({ rect }) => rect.top)); const bottom = Math.max(...rects.map(({ rect }) => rect.top + rect.height)); rects.forEach(({ object, rect }) => { let dx = 0; let dy = 0; if (mode === 'left') dx = left - rect.left; if (mode === 'centerH') dx = (left + right) / 2 - (rect.left + rect.width / 2); if (mode === 'right') dx = right - (rect.left + rect.width); if (mode === 'top') dy = top - rect.top; if (mode === 'centerV') dy = (top + bottom) / 2 - (rect.top + rect.height / 2); if (mode === 'bottom') dy = bottom - (rect.top + rect.height); object.set({ left: (object.left ?? 0) + dx, top: (object.top ?? 0) + dy }); object.setCoords(); }); active.setCoords(); c.requestRenderAll(); snapshot(); }
  function groupSelection() { const c = canvas.current; const active = c?.getActiveObject(); if (!c || !active || active.type !== 'activeselection') return; const objects = (active as fabric.ActiveSelection).getObjects().slice(); c.discardActiveObject(); c.remove(...objects); const group = new fabric.Group(objects); c.add(group); c.setActiveObject(group); c.requestRenderAll(); snapshot(); syncUi(); setStatus(`${objects.length} elementos agrupados`); }
  function ungroupSelection() { const c = canvas.current; const active = c?.getActiveObject(); if (!c || !active || active.type !== 'group') return; const objects = (active as fabric.Group).removeAll(); c.remove(active); c.add(...objects); c.setActiveObject(new fabric.ActiveSelection(objects, { canvas: c })); c.requestRenderAll(); snapshot(); syncUi(); setStatus(`${objects.length} elementos desagrupados`); }
  function cropSelected() { const o = canvas.current?.getActiveObject(); if (!o || o.type !== 'image') { setStatus('Selecciona una imagen para recortarla'); return; } o.off('mousedblclick', enterCropMode); enterCropMode.call(enterCropMode, { target: o } as fabric.TPointerEventInfo); refreshCroppedImage(o); setStatus('Modo recorte activo · doble clic para terminar'); }
  function toggleSnapping() { const next = !snappingRef.current; snappingRef.current = next; setSnapping(next); snapGuides.current = {}; canvas.current?.requestRenderAll(); setStatus(next ? 'Ajuste magnético activado' : 'Ajuste magnético desactivado'); }
  async function saveProject(silent = false) { const c = canvas.current; if (!c) return; const cleanName = name.trim() || 'Sin título'; if (!silent) setStatus('Guardando…'); try { const updatedPages = commitCurrentPage(); const effectivePageId = updatedPages.some((page) => page.id === activePageId) ? activePageId : updatedPages[0]?.id; const isRenamedCopy = Boolean(projectId && savedNameRef.current && savedNameRef.current !== cleanName); const payload = { id: isRenamedCopy ? '' : projectId, name: cleanName, width: c.width, height: c.height, background: c.backgroundColor, canvas: c.toJSON(), pages: updatedPages, activePageId: effectivePageId }; const response = await fetch('/api/projects', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) }); const result = await response.json(); if (!response.ok || !result.id) throw new Error(result.error || 'El servidor no confirmó el guardado'); setProjectId(result.id); savedNameRef.current = cleanName; const time = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); setLastSaved(time); if (!silent) setStatus(`${isRenamedCopy ? 'Copia creada' : 'Guardado verificado'} · ${result.id}.json`); await refreshProjects(); } catch (error) { setStatus(error instanceof Error ? `No se guardó: ${error.message}` : 'No se pudo guardar'); } }
  async function loadProject(id: string) { if (!id || !canvas.current) return; setStatus('Abriendo…'); const data = await (await fetch(`/api/projects/${id}`)).json(); const incoming: PageData[] = data.pages?.length ? data.pages : [{ id: `page-${Date.now()}`, name: 'Página 1', w: data.width, h: data.height, bg: data.background, json: data.canvas }]; setPagesSynced(incoming); const first = incoming.find((item) => item.id === data.activePageId) || incoming[0]; setActivePageId(first.id); restoring.current = true; canvas.current.setDimensions({ width: first.w, height: first.h }); setSize({ w: first.w, h: first.h }); setCustomWidth(String(first.w)); setCustomHeight(String(first.h)); await canvas.current.loadFromJSON(first.json); attachCrop(canvas.current); canvas.current.backgroundColor = first.bg; canvas.current.requestRenderAll(); restoring.current = false; setProjectId(data.id); setName(data.name); savedNameRef.current = data.name; history.current = []; historyIndex.current = -1; snapshot(); syncUi(); setStatus(`Proyecto abierto · ${incoming.length} página${incoming.length === 1 ? '' : 's'}`); }
  async function duplicateAndResize() { const c = canvas.current; if (!c) return; const w = Math.round(Number(customWidth)); const h = Math.round(Number(customHeight)); if (w < 64 || h < 64 || w > 10000 || h > 10000) return setStatus('Define primero medidas válidas'); commitCurrentPage(); const temp = new fabric.StaticCanvas(undefined, { width: w, height: h, backgroundColor: c.backgroundColor }); await temp.loadFromJSON(c.toJSON()); const sx = w / c.width; const sy = h / c.height; temp.getObjects().forEach((o) => o.set({ left: (o.left ?? 0) * sx, top: (o.top ?? 0) * sy, scaleX: (o.scaleX ?? 1) * sx, scaleY: (o.scaleY ?? 1) * sy })); const page: PageData = { id: `page-${Date.now()}`, name: `Página ${pagesRef.current.length + 1} · ${w}×${h}`, w, h, bg: String(c.backgroundColor || '#fff'), json: temp.toJSON() }; temp.dispose(); setPagesSynced([...pagesRef.current, page]); await openPage(page.id); setStatus(`Copia creada en ${w} × ${h}px`); }
  async function saveTemplate() { const title = window.prompt('Nombre de la plantilla', `${name} base`); if (!title) return; const body = { name: title, pages: commitCurrentPage() }; await fetch('/api/library/templates', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }); await refreshLibraries(); setStatus(`Plantilla “${title}” guardada`); }
  async function useTemplate(id: string) { const data = await (await fetch(`/api/library/templates/${id}`)).json(); if (!data.pages?.length) return; const cloned = data.pages.map((page: PageData, index: number) => ({ ...page, id: `page-${Date.now()}-${index}` })); setPagesSynced(cloned); setActivePageId(''); await openPage(cloned[0].id); setProjectId(''); setName(`${data.name} copia`); setStatus('Plantilla aplicada como documento nuevo'); }
  async function uploadBrandAssets(files: FileList | null, kind: 'logos' | 'images') { if (!files?.length) return; setBrandSaving(true); try { const uploaded: string[] = []; for (const file of [...files]) { const form = new FormData(); form.append('file', file); const response = await fetch('/api/assets', { method: 'POST', body: form }); const result = await response.json(); if (!response.ok || !result.src) throw new Error(result.error || `No se pudo subir ${file.name}`); uploaded.push(result.src); } setBrandDraft((current) => ({ ...current, [kind]: [...current[kind], ...uploaded] })); } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude subir los recursos de marca'); } finally { setBrandSaving(false); } }
  function openNewBrand() { setEditingBrandId(''); setBrandDraft({ name: '', fontFamily: 'Arial', colors: [...BRAND_PALETTES[0].colors], logos: [], images: [] }); setBrandModalOpen(true); }
  function editBrand(kit: BrandKit) { setEditingBrandId(kit.id); setBrandDraft({ name: kit.name, fontFamily: kit.fontFamily, colors: [...kit.colors], logos: [...kit.logos], images: [...kit.images] }); setBrandModalOpen(true); }
  async function saveBrand(event: React.FormEvent) { event.preventDefault(); const title = brandDraft.name.trim(); if (!title) return setStatus('Escribe un nombre para el kit'); setBrandSaving(true); try { const response = await fetch('/api/library/brands', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ ...brandDraft, id: editingBrandId, name: title }) }); const result = await response.json(); if (!response.ok || !result.id) throw new Error(result.error || 'No se confirmó el guardado'); await refreshLibraries(); setPalette(brandDraft.colors); setBrandModalOpen(false); setEditingBrandId(''); setBrandDraft({ name: '', fontFamily: 'Arial', colors: BRAND_PALETTES[0].colors, logos: [], images: [] }); setStatus(`Kit “${title}” ${editingBrandId ? 'actualizado' : 'creado'}`); } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude guardar el kit'); } finally { setBrandSaving(false); } }
  async function deleteBrand() { if (!editingBrandId || !window.confirm(`¿Eliminar el kit “${brandDraft.name}”? Los recursos originales permanecerán en assets.`)) return; setBrandSaving(true); try { const response = await fetch(`/api/library/brands/${editingBrandId}`, { method: 'DELETE' }); const result = await response.json(); if (!response.ok || !result.deleted) throw new Error(result.error || 'No se confirmó la eliminación'); if (activeBrandId === editingBrandId) setActiveBrandId(''); setBrandModalOpen(false); setEditingBrandId(''); await refreshLibraries(); setStatus(`Kit “${brandDraft.name}” eliminado`); } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude eliminar el kit'); } finally { setBrandSaving(false); } }
  async function useBrand(id: string) { const data = await (await fetch(`/api/library/brands/${id}`)).json(); if (Array.isArray(data.colors)) setPalette(data.colors); if (inspector.isText && data.fontFamily) patchObject({ fontFamily: data.fontFamily }); setActiveBrandId(id); setStatus(`Kit “${data.name}” activo · selecciona un recurso para insertarlo`); }
  async function addBrandAsset(src: string, label: string) { try { if (src.toLowerCase().includes('.svg')) { const response = await fetch(src); if (!response.ok) throw new Error('No pude leer el SVG'); const { objects, options } = await fabric.loadSVGFromString(await response.text()); const valid = objects.filter((object): object is fabric.FabricObject => Boolean(object)); if (!valid.length) throw new Error('El SVG está vacío'); const vector = fabric.util.groupSVGElements(valid, options); const scale = 320 / Math.max(vector.width || 320, vector.height || 320); vector.set({ scaleX: scale, scaleY: scale, originX: 'center', originY: 'center' }); add(vector); } else { const image = await fabric.FabricImage.fromURL(src); const scale = Math.min(600 / (image.width || 1), 600 / (image.height || 1), 1); image.scale(scale); add(image); if (canvas.current) attachCrop(canvas.current); } setStatus(`${label} insertado desde el kit de marca`); } catch (error) { setStatus(error instanceof Error ? error.message : 'No pude insertar el recurso de marca'); } }
  async function renderPages(format: 'png' | 'jpeg') { const c = canvas.current; if (!c) return []; const list = commitCurrentPage(); const active = activePageId; const output: { page: PageData; dataUrl: string }[] = []; for (const page of list) { c.setDimensions({ width: page.w, height: page.h }); await c.loadFromJSON(page.json); c.backgroundColor = page.bg; c.discardActiveObject(); c.requestRenderAll(); output.push({ page, dataUrl: c.toDataURL({ format, quality: .94, multiplier: 1 }) }); } const restore = list.find((page) => page.id === active) || list[0]; c.setDimensions({ width: restore.w, height: restore.h }); await c.loadFromJSON(restore.json); c.backgroundColor = restore.bg; attachCrop(c); c.requestRenderAll(); setSize({ w: restore.w, h: restore.h }); syncUi(); return output; }
  async function exportDocument(format: 'png' | 'jpeg' | 'svg' | 'zip' | 'pdf') { const c = canvas.current; if (!c) return; setStatus('Preparando exportación…'); if (format === 'svg') { const blob = new Blob([c.toSVG()], { type: 'image/svg+xml' }); downloadBlob(blob, `${name}.svg`); return setStatus('SVG exportado'); } const images = await renderPages(format === 'jpeg' ? 'jpeg' : 'png'); if (format === 'png' || format === 'jpeg') { const item = images.find(({ page }) => page.id === activePageId) || images[0]; const result = await (await fetch('/api/exports', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name, dataUrl: item.dataUrl }) })).json(); const a = document.createElement('a'); a.href = item.dataUrl; a.download = result.filename; a.click(); return setStatus(`Copia guardada en ${result.path}`); } if (format === 'zip') { const JSZip = (await import('jszip')).default; const zip = new JSZip(); images.forEach(({ page, dataUrl }, index) => zip.file(`${String(index + 1).padStart(2, '0')}-${page.name}.png`, dataUrl.split(',')[1], { base64: true })); downloadBlob(await zip.generateAsync({ type: 'blob' }), `${name}.zip`); return setStatus('Páginas exportadas como ZIP'); } const { jsPDF } = await import('jspdf'); const first = images[0].page; const pdf = new jsPDF({ orientation: first.w >= first.h ? 'landscape' : 'portrait', unit: 'px', format: [first.w, first.h] }); images.forEach(({ page, dataUrl }, index) => { if (index) pdf.addPage([page.w, page.h], page.w >= page.h ? 'landscape' : 'portrait'); pdf.addImage(dataUrl, 'PNG', 0, 0, page.w, page.h); }); pdf.save(`${name}.pdf`); setStatus('PDF exportado'); }
  function downloadBlob(blob: Blob, filename: string) { const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url); }

  useEffect(() => { const key = (e: KeyboardEvent) => { if ((e.target as HTMLElement)?.matches('input, textarea, select')) return; if ((e.ctrlKey || e.metaKey) && e.key === 'z') { e.preventDefault(); void travel(e.shiftKey ? 1 : -1); } if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') { e.preventDefault(); void saveProject(); } if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'd') { e.preventDefault(); void duplicate(); } if ((e.key === 'Delete' || e.key === 'Backspace')) remove(); }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); });
  useEffect(() => { const timer = window.setInterval(() => { if (projectId) void saveProject(true); }, 60_000); return () => window.clearInterval(timer); });
  useEffect(() => { if (!brandModalOpen) return; const close = (event: KeyboardEvent) => { if (event.key === 'Escape') setBrandModalOpen(false); }; const previous = document.body.style.overflow; document.body.style.overflow = 'hidden'; window.addEventListener('keydown', close); return () => { document.body.style.overflow = previous; window.removeEventListener('keydown', close); }; }, [brandModalOpen]);
  useEffect(() => {
    const selector = 'aside.sidebar > section';
    const initialize = () => {
      const sections = [...document.querySelectorAll<HTMLElement>(selector)];
      sections.forEach((section) => {
        if (section.dataset.accordionReady) return;
        section.dataset.accordionReady = 'true';
        section.classList.add('accordion-section');
        const heading = section.querySelector<HTMLElement>(':scope > h2');
        if (!heading) return;
        heading.setAttribute('role', 'button');
        heading.tabIndex = 0;
        const shouldOpen = document.querySelectorAll(`${selector}.accordion-open`).length < 2;
        section.classList.toggle('accordion-open', shouldOpen);
        heading.setAttribute('aria-expanded', String(shouldOpen));
      });
    };
    const toggle = (heading: HTMLElement) => {
      const section = heading.parentElement;
      if (!section?.matches(selector)) return;
      const opening = !section.classList.contains('accordion-open');
      if (opening) {
        const open = [...document.querySelectorAll<HTMLElement>(`${selector}.accordion-open`)].filter((item) => item !== section);
        while (open.length >= 2) {
          const oldest = open.shift();
          oldest?.classList.remove('accordion-open');
          oldest?.querySelector(':scope > h2')?.setAttribute('aria-expanded', 'false');
        }
      }
      section.classList.toggle('accordion-open', opening);
      heading.setAttribute('aria-expanded', String(opening));
    };
    const click = (event: Event) => { const heading = (event.target as HTMLElement).closest<HTMLElement>('aside.sidebar > section > h2'); if (heading) toggle(heading); };
    const key = (event: KeyboardEvent) => { const heading = (event.target as HTMLElement).closest<HTMLElement>('aside.sidebar > section > h2'); if (heading && (event.key === 'Enter' || event.key === ' ')) { event.preventDefault(); toggle(heading); } };
    initialize();
    const observer = new MutationObserver(initialize); observer.observe(document.querySelector('.workspace') || document.body, { childList: true, subtree: true });
    document.addEventListener('click', click); document.addEventListener('keydown', key);
    return () => { observer.disconnect(); document.removeEventListener('click', click); document.removeEventListener('keydown', key); };
  }, []);

  return <main className="app-shell">
    <header className="topbar">
      <div className="brand"><span className="brand-mark">F</span><div><strong>Taller Fabric</strong><small>Editor local</small></div></div>
      <label className="project-name"><span>Nombre del proyecto</span><input value={name} onChange={(e) => setName(e.target.value)} /></label>
      <div className="top-actions"><span className="save-time">{lastSaved}</span><button type="button" className="button ghost" onClick={() => void saveProject()}><Save /> Guardar</button><select className="export-select" aria-label="Formato de exportación" defaultValue="" onChange={(e) => { if (e.target.value) void exportDocument(e.target.value as 'png' | 'jpeg' | 'svg' | 'zip' | 'pdf'); e.target.value = ''; }}><option value="">Exportar…</option><option value="png">PNG actual</option><option value="jpeg">JPEG actual</option><option value="svg">SVG actual</option><option value="zip">Todas · ZIP</option><option value="pdf">Todas · PDF</option></select><button type="button" className="button primary" onClick={() => void exportDocument('png')}><Download /> PNG</button></div>
    </header>
    <div className="workspace">
      <aside className="sidebar left-panel">
        <section><h2>Agregar</h2><div className="tool-grid"><button onClick={addText}><Type/><span>Texto</span></button><button onClick={addRect}><Square/><span>Rectángulo</span></button><button onClick={addCircle}><Circle/><span>Círculo</span></button><label className="tool"><ImagePlus/><span>Imagen</span><input type="file" accept="image/*" hidden onChange={(e) => void uploadImage(e.target.files?.[0])}/></label></div></section>
        <section><h2>Lienzo</h2><label className="field">Formato<select value={SIZES.some((s) => s.w === size.w && s.h === size.h) ? `${size.w}x${size.h}` : 'custom'} onChange={(e) => { if (e.target.value === 'custom') return; const [w,h] = e.target.value.split('x').map(Number); resize(w,h); }}>{SIZES.map((s) => <option key={s.name} value={`${s.w}x${s.h}`}>{s.name} · {s.w}×{s.h}</option>)}<option value="custom">Personalizado · {size.w}×{size.h}</option></select></label><div className="custom-size"><label>Ancho<input type="number" min="64" max="10000" inputMode="numeric" value={customWidth} onChange={(e) => setCustomWidth(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') applyCustomSize(); }}/></label><span>×</span><label>Alto<input type="number" min="64" max="10000" inputMode="numeric" value={customHeight} onChange={(e) => setCustomHeight(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') applyCustomSize(); }}/></label></div><button className="apply-size" onClick={applyCustomSize}>Aplicar tamaño libre</button><button className="secondary-size" onClick={() => void duplicateAndResize()}>Duplicar y redimensionar</button><p className="size-help">De 64 a 10,000 px por lado.</p><label className="field">Fondo<input type="color" value={String(canvas.current?.backgroundColor || '#ffffff')} onChange={(e) => { if (canvas.current) { canvas.current.backgroundColor = e.target.value; canvas.current.requestRenderAll(); snapshot(); } }}/></label></section>
        <section><h2>Biblioteca</h2><div className="media-tabs"><button className={mediaMode === 'photos' ? 'active' : ''} onClick={() => setMediaMode('photos')}>Fotos</button><button className={mediaMode === 'icons' ? 'active' : ''} onClick={() => setMediaMode('icons')}>Iconos</button></div><form className="media-search" onSubmit={(e) => void searchMedia(e)}><input aria-label={mediaMode === 'photos' ? 'Buscar en Pexels' : 'Buscar en Iconify'} value={mediaQuery} onChange={(e) => setMediaQuery(e.target.value)} placeholder={mediaMode === 'photos' ? 'Buscar fotos…' : 'Buscar iconos…'}/><button disabled={mediaLoading}>{mediaLoading ? '…' : 'Buscar'}</button></form>{mediaMode === 'photos' ? <div className="media-grid">{media.map((item) => <button key={item.id} onClick={() => void addStockImage(item)} title={`${item.alt} · ${item.photographer}`}><img src={item.thumb} alt={item.alt || `Foto de ${item.photographer}`}/><span>{item.photographer}</span></button>)}</div> : <div className="icon-grid">{icons.map((icon) => { const [prefix, iconName] = icon.split(':'); return <button key={icon} title={icon} onClick={() => void addIcon(icon)}><img src={`/api/media/icons/${prefix}/${iconName}?color=%2318181b`} alt=""/><span>{iconName}</span></button>; })}</div>}</section>
        <section><h2>Abrir proyecto</h2><select aria-label="Abrir proyecto" value="" onChange={(e) => void loadProject(e.target.value)}><option value="">Seleccionar…</option>{projects.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select><p className="hint"><FolderOpen/> {projects.length} guardado{projects.length === 1 ? '' : 's'} localmente</p></section>
        <section><h2>Plantillas</h2><button className="wide-action" onClick={() => void saveTemplate()}><Save/> Guardar como plantilla</button><select aria-label="Usar plantilla" value="" onChange={(e) => void useTemplate(e.target.value)}><option value="">Usar una plantilla…</option>{templates.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></section>
        <section><h2>Kits de marca</h2><button className="wide-action" onClick={openNewBrand}><Plus/> Crear kit de marca</button><div className="brand-grid">{brands.map((kit) => { const preview = kit.images[0] || kit.logos[0]; return <button key={kit.id} className={`brand-card ${kit.id === activeBrandId ? 'active' : ''}`} onClick={() => void useBrand(kit.id)} onDoubleClick={(event) => { event.preventDefault(); editBrand(kit); }} title="Clic para activar · doble clic para editar"><div className="brand-visual">{preview ? <img src={preview} alt=""/> : <span style={{ background: kit.colors[0] || '#eee' }}/>}<div className="brand-colors">{kit.colors.slice(0,3).map((color) => <i key={color} style={{ background: color }}/>)}</div></div><strong style={{ fontFamily: kit.fontFamily }}>{kit.name}</strong><small>{kit.fontFamily}</small></button>; })}</div>{activeBrandId && (() => { const kit = brands.find((item) => item.id === activeBrandId); if (!kit) return null; return <div className="brand-assets"><h3>Recursos de {kit.name}</h3>{kit.logos.length > 0 && <><small>Logos</small><div>{kit.logos.map((src, index) => <button key={src} onClick={() => void addBrandAsset(src, `Logo ${index + 1}`)} title="Insertar logo"><img src={src} alt={`Logo ${index + 1}`}/></button>)}</div></>}{kit.images.length > 0 && <><small>Imágenes</small><div>{kit.images.map((src, index) => <button key={src} onClick={() => void addBrandAsset(src, `Imagen ${index + 1}`)} title="Insertar imagen"><img src={src} alt={`Imagen ${index + 1}`}/></button>)}</div></>}{!kit.logos.length && !kit.images.length && <p className="size-help">Este kit no tiene recursos visuales.</p>}</div>; })()}{!brands.length && <p className="size-help">Todavía no hay kits. Crea el primero.</p>}</section>
      </aside>
      <section className="stage-column">
        <div className="stage-toolbar"><div><button aria-label="Deshacer" disabled={!canUndo} onClick={() => void travel(-1)}><Undo2/></button><button aria-label="Rehacer" disabled={!canRedo} onClick={() => void travel(1)}><Redo2/></button><span className="divider"/><button aria-label="Duplicar" disabled={!selected} onClick={() => void duplicate()}><Copy/></button><button aria-label="Eliminar" disabled={!selected} onClick={remove}><Trash2/></button><span className="divider"/><button className={snapping ? 'is-active' : ''} aria-label={snapping ? 'Desactivar ajuste magnético' : 'Activar ajuste magnético'} aria-pressed={snapping} onClick={toggleSnapping}><Magnet/></button></div><label className="zoom">{zoom}%<input type="range" min="20" max="90" value={zoom} onChange={(e) => setZoom(Number(e.target.value))}/></label></div>
        <div className="stage"><div className="canvas-frame" style={{ width: size.w * zoom / 100, height: size.h * zoom / 100 }}><div style={{ transform: `scale(${zoom / 100})`, transformOrigin: 'top left' }}><canvas ref={canvasNode}/></div></div></div>
        <div className="page-strip"><button className="add-page" onClick={() => addPage(false)}><FilePlus2/> Nueva</button>{pages.map((page, index) => <div key={page.id} className={`page-chip ${page.id === activePageId ? 'active' : ''}`}><button onClick={() => void openPage(page.id)} onDoubleClick={() => renamePage(page.id)} title="Doble clic para renombrar">{page.thumb ? <img src={page.thumb} alt=""/> : <span>{index + 1}</span>}<small>{page.name}</small></button><div><button disabled={index === 0} onClick={() => movePage(page.id, -1)}>←</button><button onClick={() => { if (page.id === activePageId) addPage(true); }}>＋</button><button disabled={pages.length === 1} onClick={() => void deletePage(page.id)}>×</button><button disabled={index === pages.length - 1} onClick={() => movePage(page.id, 1)}>→</button></div></div>)}</div>
        <footer className="status"><span className="status-dot"/>{status}<span>{size.w} × {size.h}px</span></footer>
      </section>
      <aside className="sidebar right-panel">
        <section><h2>Propiedades</h2>{selected ? <><label className="field">Color<input type="color" value={inspector.fill} onChange={(e) => patchObject({ fill: e.target.value })}/></label>{inspector.isText && <div className="text-tools"><label>Fuente<select value={inspector.fontFamily} onChange={(e) => patchObject({ fontFamily: e.target.value })}><option>Arial</option><option>Georgia</option><option>Verdana</option><option>Trebuchet MS</option><option>Courier New</option><option>Times New Roman</option></select></label><label>Tamaño<input type="number" min="8" max="500" value={inspector.fontSize} onChange={(e) => patchObject({ fontSize: Number(e.target.value) })}/></label><div className="text-buttons"><button className={Number(inspector.fontWeight) >= 600 ? 'active' : ''} onClick={() => patchObject({ fontWeight: Number(inspector.fontWeight) >= 600 ? 400 : 700 })}><b>B</b></button><button className={inspector.fontStyle === 'italic' ? 'active' : ''} onClick={() => patchObject({ fontStyle: inspector.fontStyle === 'italic' ? 'normal' : 'italic' })}><i>I</i></button><button className={inspector.underline ? 'active' : ''} onClick={() => patchObject({ underline: !inspector.underline })}><u>U</u></button><select aria-label="Alineación del texto" value={inspector.textAlign} onChange={(e) => patchObject({ textAlign: e.target.value })}><option value="left">Izq.</option><option value="center">Centro</option><option value="right">Der.</option><option value="justify">Justificar</option></select></div><label>Espaciado <span>{inspector.charSpacing}</span><input type="range" min="-100" max="500" value={inspector.charSpacing} onChange={(e) => patchObject({ charSpacing: Number(e.target.value) })}/></label><label>Interlínea <span>{inspector.lineHeight.toFixed(1)}</span><input type="range" min="0.7" max="2.5" step="0.1" value={inspector.lineHeight} onChange={(e) => patchObject({ lineHeight: Number(e.target.value) })}/></label></div>}<label className="field">Opacidad <span>{inspector.opacity}%</span><input type="range" min="5" max="100" value={inspector.opacity} onChange={(e) => patchObject({ opacity: Number(e.target.value) / 100 })}/></label><label className="field">Rotación <span>{inspector.angle}°</span><input type="range" min="-180" max="180" value={inspector.angle} onChange={(e) => patchObject({ angle: Number(e.target.value) })}/></label>{inspector.canRound && <label className="field">Radio de esquinas <span>{inspector.radius}%</span><input type="range" min="0" max="100" value={inspector.radius} onChange={(e) => applyRadius(Number(e.target.value))}/></label>}<div className="effect-row"><label><input type="checkbox" checked={inspector.shadowOn} onChange={(e) => applyShadow(e.target.checked)}/> Sombra</label>{inspector.shadowOn && <span>{inspector.shadowIntensity}%</span>}</div>{inspector.shadowOn && <label className="field shadow-slider">Intensidad<input type="range" min="0" max="100" value={inspector.shadowIntensity} onChange={(e) => applyShadow(true, Number(e.target.value))}/></label>}{inspector.isImage && <><button className="wide-action" onClick={cropSelected}><Crop/> Recortar imagen</button><label className="wide-action"><ImagePlus/> Reemplazar imagen<input type="file" accept="image/*" hidden onChange={(e) => void replaceImage(e.target.files?.[0])}/></label></>}<div className="row"><button onClick={center}><AlignCenter/> Centrar</button><button onClick={() => layer('front')}><BringToFront/> Frente</button><button onClick={() => layer('back')}><SendToBack/> Fondo</button></div></> : <div className="empty">Selecciona un elemento para editarlo.</div>}</section>
        {selected && <section><h2>Alinear</h2><p className="section-help">{selectionType === 'multiple' ? 'Respecto a la selección' : 'Respecto al lienzo'}</p><div className="align-grid"><button title="Izquierda" aria-label="Alinear a la izquierda" onClick={() => selectionType === 'multiple' ? alignSelection('left') : alignToCanvas('left')}><AlignHorizontalJustifyStart/></button><button title="Centro horizontal" aria-label="Centrar horizontalmente" onClick={() => selectionType === 'multiple' ? alignSelection('centerH') : alignToCanvas('centerH')}><AlignHorizontalJustifyCenter/></button><button title="Derecha" aria-label="Alinear a la derecha" onClick={() => selectionType === 'multiple' ? alignSelection('right') : alignToCanvas('right')}><AlignHorizontalJustifyEnd/></button><button title="Arriba" aria-label="Alinear arriba" onClick={() => selectionType === 'multiple' ? alignSelection('top') : alignToCanvas('top')}><AlignVerticalJustifyStart/></button><button title="Centro vertical" aria-label="Centrar verticalmente" onClick={() => selectionType === 'multiple' ? alignSelection('centerV') : alignToCanvas('centerV')}><AlignVerticalJustifyCenter/></button><button title="Abajo" aria-label="Alinear abajo" onClick={() => selectionType === 'multiple' ? alignSelection('bottom') : alignToCanvas('bottom')}><AlignVerticalJustifyEnd/></button></div>{selectionType === 'multiple' && <button className="wide-action" onClick={groupSelection}><Group/> Agrupar selección</button>}{selectionType === 'group' && <button className="wide-action" onClick={ungroupSelection}><Ungroup/> Desagrupar</button>}</section>}
        <section className="layers"><h2><Layers3/> Capas <span>{layers.length}</span></h2><p className="section-help">Arrastra para ordenar · Shift/Ctrl para seleccionar varias · doble clic para renombrar.</p>{layers.length ? layers.map((o, i) => <div key={`${o.type}-${i}`} draggable onDragStart={(e) => e.dataTransfer.setData('text/layer-index', String(i))} onDragOver={(e) => e.preventDefault()} onDrop={(e) => reorderLayer(Number(e.dataTransfer.getData('text/layer-index')), i)} className={`layer-row ${canvas.current?.getActiveObjects().includes(o) ? 'active' : ''}`}><button className="layer-main" onClick={(e) => selectLayer(e, o)} onDoubleClick={() => renameLayer(o)}><span className="layer-icon">{o.type === 'textbox' ? 'T' : o.type === 'image' ? 'IMG' : '◆'}</span><span>{String((o as fabric.FabricObject & { name?: string }).name || (o.type === 'textbox' ? (o as fabric.Textbox).text : `${o.type} ${layers.length - i}`)).slice(0, 18)}</span></button><button aria-label={o.visible ? 'Ocultar capa' : 'Mostrar capa'} onClick={() => toggleLayerVisible(o)}>{o.visible ? <Eye/> : <EyeOff/>}</button><button aria-label={o.selectable === false ? 'Desbloquear capa' : 'Bloquear capa'} onClick={() => toggleLayerLock(o)}>{o.selectable === false ? <Lock/> : <Unlock/>}</button></div>) : <div className="empty">Tu lienzo está vacío.</div>}</section>
        <section><h2>Paleta rápida</h2><div className="swatches">{palette.map((color) => <button key={color} aria-label={`Usar ${color}`} style={{ background: color }} onClick={() => selected ? patchObject({ fill: color }) : undefined}/>)}</div></section>
      </aside>
    </div>
    {brandModalOpen && <div className="modal-backdrop" role="presentation" onMouseDown={(e) => { if (e.target === e.currentTarget) setBrandModalOpen(false); }}><div className="brand-modal" role="dialog" aria-modal="true" aria-labelledby="brand-modal-title"><header><div><span>Identidad visual</span><h2 id="brand-modal-title">{editingBrandId ? 'Editar kit de marca' : 'Crear kit de marca'}</h2></div><button type="button" aria-label="Cerrar" onClick={() => setBrandModalOpen(false)}><X/></button></header><form onSubmit={(e) => void saveBrand(e)}><label className="modal-field">Nombre del kit<input autoFocus required value={brandDraft.name} onChange={(e) => setBrandDraft((current) => ({ ...current, name: e.target.value }))} placeholder="Ej. Marca principal"/></label><label className="modal-field">Tipografía<select value={brandDraft.fontFamily} onChange={(e) => setBrandDraft((current) => ({ ...current, fontFamily: e.target.value }))}><option>Arial</option><option>Georgia</option><option>Verdana</option><option>Trebuchet MS</option><option>Courier New</option><option>Times New Roman</option></select></label><label className="modal-field">Paleta base<select onChange={(e) => { const chosen = BRAND_PALETTES[Number(e.target.value)]; if (chosen) setBrandDraft((current) => ({ ...current, colors: [...chosen.colors] })); }}>{BRAND_PALETTES.map((item, index) => <option key={item.name} value={index}>{item.name}</option>)}</select></label><fieldset><legend>Colores</legend><div className="brand-color-editors">{brandDraft.colors.map((color, index) => <label key={index}><input type="color" value={color} onChange={(e) => setBrandDraft((current) => ({ ...current, colors: current.colors.map((item, itemIndex) => itemIndex === index ? e.target.value : item) }))}/><span>{color}</span></label>)}</div></fieldset><div className="asset-upload-grid"><label><strong>Logos</strong><span>PNG, JPG, WebP o SVG</span><input type="file" accept="image/*,.svg" multiple onChange={(e) => void uploadBrandAssets(e.target.files, 'logos')}/></label><label><strong>Imágenes</strong><span>Fotos y recursos de marca</span><input type="file" accept="image/*" multiple onChange={(e) => void uploadBrandAssets(e.target.files, 'images')}/></label></div>{(brandDraft.logos.length > 0 || brandDraft.images.length > 0) && <div className="asset-preview">{[...brandDraft.logos, ...brandDraft.images].map((src) => <img key={src} src={src} alt=""/>)}</div>}<footer>{editingBrandId && <button type="button" className="button danger" onClick={() => void deleteBrand()} disabled={brandSaving}><Trash2/> Eliminar kit</button>}<span className="modal-spacer"/><button type="button" className="button ghost" onClick={() => setBrandModalOpen(false)}>Cancelar</button><button type="submit" className="button primary" disabled={brandSaving}>{brandSaving ? 'Guardando…' : editingBrandId ? 'Guardar cambios' : 'Crear kit'}</button></footer></form></div></div>}
  </main>;
}
